import{_ as a,o as n,c as s,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Persistent shared colony","description":"","frontmatter":{"pageId":"players/coop","contentRevision":5},"headers":[],"relativePath":"en/players/coop.md","filePath":"en/players/coop.md"}'),r={name:"en/players/coop.md"};function t(i,e,c,l,h,p){return n(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="persistent-shared-colony" tabindex="-1">Persistent shared colony <a class="header-anchor" href="#persistent-shared-colony" aria-label="Permalink to &quot;Persistent shared colony&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>The owner opens <strong>Shared colony</strong> below chat and invites a partner.</li><li>The partner opens the same window, refreshes and accepts.</li><li>The owner assigns free colonists on the home map.</li><li>From their own home colony, the partner chooses <strong>Join colony</strong>. Their home is saved before loading the mirror.</li><li>The partner controls assigned pawns, including work, schedules, equipment and combat; the owner continues playing and writes the only canonical save.</li></ol><p>Membership survives restart. Changing assignments or revoking membership ends the current session. The partner leaves to return home.</p><h2 id="coop-check" tabindex="-1">Who controls what after an invitation? <a class="header-anchor" href="#coop-check" aria-label="Permalink to &quot;Who controls what after an invitation? {#coop-check}&quot;">​</a></h2><p>Invitation, acceptance, pawn assignment and joining are four separate steps. Membership alone does not grant control of the settlement. The owner must assign free colonists on the chosen home map; the partner must start from their own home colony.</p><p>For a first check, assign one pawn and leave another unassigned. Have the partner change the assigned pawn&#39;s work/schedule and verify execution on the host. The unassigned pawn must not accept partner orders. Leave and rejoin: membership persists, pawns remain with the host, and the partner receives no “return” parcels containing host colonists.</p><p>Assignment grants real trust over equipment and combat orders. Do not give it merely for a tour; use an ordinary/live visit instead.</p><h2 id="coop-recovery" tabindex="-1">Revocation, busy sessions and reassignment <a class="header-anchor" href="#coop-recovery" aria-label="Permalink to &quot;Revocation, busy sessions and reassignment {#coop-recovery}&quot;">​</a></h2><p>One partner can join at a time; eight invitations/members and 32 assigned pawns are storage/permission limits, not concurrent-client counts. A busy refusal is not fixed by a second account.</p><p>Reassignment or revocation ends current coop. Rollback preserves membership but clears assignments: an old numeric pawn ID may identify a different object. Reset removes colony permissions; archive/restore preserves membership but ends active live sessions.</p><p>If the owner leaves, there is no autonomous continuation. A retained mirror is not a second canonical save. Administrators can inspect/revoke membership, not fix a session by granting pawn copies.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>One concurrent partner, up to 8 invitations/members and 32 pawns. The owner must be online at home. Wallet, transfer and admin permissions are not shared. Reset removes membership; archive/restore preserves it; rollback keeps membership but clears assignments. Owner pawns are not mailed to the partner.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: the active map</a></li><li><a href="./../admins/administration">Panel and moderation</a></li><li><a href="./saves-recovery">Saves and recovery</a></li></ul>',17)])])}const u=a(r,[["render",t]]);export{m as __pageData,u as default};
